<p class="eyebrow"><?= $e($t('STEWARDSHIP · PRIVATE')) ?></p><h1><?= $e($t('claims')) ?></h1><p><?= $e($t('Resolving a report records the steward’s review. It does not settle ownership.')) ?></p><?php if (!$claims): ?><p class="empty"><?= $e($t('empty')) ?></p><?php endif ?><?php foreach ($claims as $claim): ?><article class="card"><span class="badge"><?= $e($claim['status']) ?></span><h2><?= $e($claim['reporter_name']) ?></h2><a href="mailto:<?= $e($claim['reporter_contact']) ?>"><?= $e($claim['reporter_contact']) ?></a><p class="preserve"><?= $e($claim['reason']) ?></p><a href="/dashboard/stories/<?= $e($claim['story_id']) ?>"><?= $e($claim['story_id']) ?></a><form data-api="/api/claims/<?= $e($claim['id']) ?>" data-method="PATCH" data-reload><label><?= $e($t('Review status')) ?><select name="status"><option value="OPEN"><?= $e($t('Open')) ?></option><option value="RESOLVED" <?= $claim['status'] === 'RESOLVED' ? 'selected' : '' ?>><?= $e($t('Reviewed / resolved')) ?></option></select></label><button class="button secondary"><?= $e($t('Save review')) ?></button><p class="form-message" role="status" aria-live="polite"></p></form></article><?php endforeach ?>
